sp_widget.css:
/* Contenitore principale (simile a .panel) */
.panel {
  border-radius: 12px;
  border: 1px solid #dcdcdc;
  padding: 20px;
  background-color: #fefefe;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03);
}

/* Tabella (simile a .table-rounded) */
table.table {
  border: 1px solid #e0e0e0;
  border-radius: 12px;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
  width: 100%;
  background-color: #ffffff;
}

/* Intestazione tabella */
table.table thead {
  background-color: #f3f7fb; /* azzurro molto chiaro */
}

table.table th {
  padding: 12px 16px;
  font-weight: 600;
  text-align: left;
  color: #2f4f4f;
  border-bottom: 1px solid #f0f0f0; /* Cambiato da #e0e0e0 a #f0f0f0 per coerenza */
}

/* Righe della tabella */
table.table td {
  padding: 12px 16px;
  border-bottom: 1px solid #f0f0f0;
  color: #333;
}

/* Riga alternata chiara */
table.table tbody tr:nth-child(even) {
  background-color: #fafafa; /* grigio molto chiaro per righe alternate */
}

/* Titolo h3 (simile a .section-title) */
h3 {
  font-size: 20px;
  margin-bottom: 20px; /* Aggiunto margine inferiore */
  display: flex; /* Permette allineamento con icona se aggiunta */
  align-items: center; /* Allinea verticalmente con icona */
  color: #007863;
}

/* Stili per la disponibilità (simili a .label-status) */
.text-success {
  font-size: 14px;
  padding: 5px 10px;
  border-radius: 12px;
  display: inline-block;
  min-width: 60px;
  text-align: center;
  filter: none !important;
  background-color: #b7e4c7 !important; /* Colore di sfondo di .label-success */
  color: #1b4332 !important; /* Colore testo di .label-success */
}

.text-danger {
  font-size: 14px;
  padding: 5px 10px;
  border-radius: 12px;
  display: inline-block;
  min-width: 60px;
  text-align: center;
  filter: none !important;
  background-color: #f8d7da !important; /* Colore di sfondo di .label-danger */
  color: #721c24 !important; /* Colore testo di .label-danger */
}

sp_widget.script:
(function() {
  var userSysId = gs.getUserID();
  var grUserGroup = new GlideRecord('sys_user_grmember');
  grUserGroup.addQuery('user', userSysId);
  grUserGroup.query();

  var isOperatore = false;
  var gruppoOperatoriId = '5ccf0ffcc3a12210e9a97205e4013131';

  while (grUserGroup.next()) {
    if (grUserGroup.group.toString() === gruppoOperatoriId) {
      isOperatore = true;
      break;
    }
  }

  data.isOperatore = isOperatore;
  data.veicoli = [];

  if (isOperatore) {
    var categorieOrdinate = ['Elettrica', 'Berlina', 'SUV', 'Utilitaria'];
    var veicoliPerCategoria = {};

    // Inizializza gli array per ciascuna categoria
    categorieOrdinate.forEach(function(categoria) {
      veicoliPerCategoria[categoria] = [];
    });

    var grVeicoli = new GlideRecord('x_1763019_furgonch_veicolo');
    grVeicoli.query();
    while (grVeicoli.next()) {
      var categoria = grVeicoli.getDisplayValue('categoria');
      var veicolo = {
        categoria: categoria,
        marca: grVeicoli.getDisplayValue('marca'),
        modello: grVeicoli.getDisplayValue('modello'),
        costoGiornaliero: grVeicoli.getDisplayValue('costo_giornaliero'),
        disponibilita: grVeicoli.getDisplayValue('disponibile')
      };

      if (!veicoliPerCategoria[categoria]) {
        veicoliPerCategoria[categoria] = []; // nel caso ci sia una categoria inattesa
      }

      veicoliPerCategoria[categoria].push(veicolo);
    }

    // Ordina i veicoli per marca all’interno di ogni categoria
    categorieOrdinate.forEach(function(categoria) {
      veicoliPerCategoria[categoria].sort(function(a, b) {
        return a.marca.localeCompare(b.marca);
      });
    });

    // Costruisce la lista finale rispettando l’ordine delle categorie
    categorieOrdinate.forEach(function(categoria) {
      data.veicoli = data.veicoli.concat(veicoliPerCategoria[categoria]);
    });
  }
})();
